    static constexpr std::array<std::string_view, dimension> joint_names = {"base_x_joint", "base_y_joint", "base_theta_joint", "joint_lift", "joint_arm", "joint_wrist_yaw", "joint_wrist_pitch", "joint_wrist_roll"};
